export type Vec3=[number,number,number];
export type RenderFinish="plain"|"tile"|"marble"|"wood"|"panel"|"acp";
export type RenderBox={lo:Vec3;hi:Vec3;color:Vec3;opacity:number;metal:number;rough:number;finish?:RenderFinish};
export type RenderLight={position:Vec3;color:Vec3;power:number};
export type RenderSnapshot={boxes:RenderBox[];camera:{origin:Vec3;forward:Vec3;right:Vec3;up:Vec3;fov:number;aspect?:number};evening:boolean;lights?:RenderLight[]};
export type RenderJob=RenderSnapshot&{width:number;height:number;samples:number};
export type RenderFrame={pixels:Uint8ClampedArray;width:number;height:number;completed:number;samples:number};
export function materialVariation(finish:RenderFinish|undefined,p:Vec3,n:Vec3):number;
export function intersectBox(o:Vec3,d:Vec3,lo:Vec3,hi:Vec3,limit?:number):{t:number;normal:Vec3}|null;
export function renderScene(job:RenderJob,report:(frame:RenderFrame)=>void):void;
